423	function buyBtc(amount) {
424	  var state = StateManager.getState();
425	  var inv = state.investment;
426	  var cost = Math.round(inv.btcPrice * amount * 100) / 100;
427	  if (state.resources.cash < cost) {
428	    StateManager.addMessage("现金不足", "danger");
429	    return;
430	  }
431	  state.resources.cash -= cost;
432	  // 追踪加权平均成本
433	  var oldTotal = (inv.btcAvgCost || 0) * (inv.btcHoldings || 0);
434	  var newTotal = oldTotal + cost;
435	  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
436	  inv.btcAvgCost = inv.btcHoldings > 0 ? Math.round(newTotal / inv.btcHoldings * 100) / 100 : 0;
437	  StateManager.addMessage("买入 " + amount + " BTC, 均价 ¥" + inv.btcAvgCost.toLocaleString(), "success");
438	}
439	
440	function sellBtc(amount) {
441	  var state = StateManager.getState();
442	  var inv = state.investment;
443	  if (inv.btcHoldings < amount) {
444	    StateManager.addMessage("持仓不足", "danger");
445	    return;
446	  }
447	  var curPrice = inv.btcPrice;
448	  var revenue = Math.round(curPrice * amount * 100) / 100;
449	  var avgCost = inv.btcAvgCost || 0;
450	  var pl = avgCost > 0 ? Math.round((curPrice - avgCost) * amount) : 0;
451	  var plStr = pl !== 0 ? (pl > 0 ? " 📈+" : " 📉") + pl : "";
452	  state.resources.cash += revenue;
453	  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
454	  // 清仓时重置成本
455	  if (inv.btcHoldings <= 0) inv.btcAvgCost = 0;
456	  StateManager.addMessage("卖出 " + amount + " BTC, 到手 ¥" + Math.round(revenue).toLocaleString() + plStr, "success");
457	}
