484	function sellProperty(propId) {
485	  var state = StateManager.getState();
486	  var inv = state.investment;
487	  var idx = -1;
488	  for (var i = 0; i < inv.properties.length; i++) {
489	    if (inv.properties[i].id === propId) {
490	      idx = i;
491	      break;
492	    }
493	  }
494	  if (idx < 0) return;
495	  var prop = inv.properties[idx];
496	  var net = prop.currentPrice - Math.round(prop.currentPrice * 0.05);
497	  state.resources.cash += net;
498	  inv.properties.splice(idx, 1);
499	  StateManager.addMessage("出售" + prop.name + " 到手" + net, "success");
500	}
