526	  state.player.actionPoints = Math.min(
527	    state.player.maxActionPoints,
528	    state.player.actionPoints + car.travelBonus,
529	  );
530	  StateManager.addMessage(
531	    "购入" + car.name + " 行动力上限+" + car.travelBonus,
532	    "success",
533	  );
534	}
