536	// ============================================================
537	//  Canvas 涨跌曲线图
538	// ============================================================
539	function drawPriceChart(canvasId, priceData, color) {
540	  var canvas =
541	    typeof canvasId === "string" ? document.getElementById(canvasId) : canvasId;
542	  if (!canvas) return;
543	  var ctx = canvas.getContext("2d");
544	  var W = canvas.width,
545	    H = canvas.height;
546	  ctx.clearRect(0, 0, W, H);
547	
548	  var data = (priceData || []).slice(-20);
549	  if (data.length < 2) {
550	    // 无历史数据时：画一条水平线 + 首日上市提示
551	    ctx.strokeStyle = color || "#888";
552	    ctx.lineWidth = 2;
553	    ctx.beginPath();
554	    ctx.moveTo(4, H / 2);
555	    ctx.lineTo(W - 4, H / 2);
556	    ctx.stroke();
557	    ctx.fillStyle = "#888";
558	    ctx.font = "11px sans-serif";
559	    ctx.textAlign = "center";
560	    ctx.fillText("今日首日上市", W / 2, H / 2 - 12);
561	    // 若有当前价格则显示
562	    var curPrice = null;
563	    if (priceData && priceData.length === 1) curPrice = priceData[0].price;
564	    if (curPrice !== null) {
565	      ctx.fillStyle = color || "#4fc3f7";
566	      ctx.font = "bold 11px sans-serif";
567	      ctx.fillText("¥" + curPrice.toFixed(2), W / 2, H / 2 + 18);
568	    }
569	    return;
570	  }
571	
572	  var prices = [];
573	  for (var i = 0; i < data.length; i++) prices.push(data[i].price);
574	
575	  var minP = prices[0],
576	    maxP = prices[0];
577	  for (var i = 1; i < prices.length; i++) {
578	    if (prices[i] < minP) minP = prices[i];
579	    if (prices[i] > maxP) maxP = prices[i];
580	  }
581	  var range = maxP - minP;
582	  if (range === 0) range = minP * 0.1 || 1;
583	  var padT = 4,
584	    padB = 4,
585	    padL = 4,
586	    padR = 4;
587	  var chartW = W - padL - padR;
588	  var chartH = H - padT - padB;
589	
590	  // 网格线
591	  if (ctx.strokeStyle) {
592	    ctx.strokeStyle = "rgba(255,255,255,0.06)";
593	    ctx.lineWidth = 0.5;
594	    for (var i = 0; i < 4; i++) {
595	      var y = padT + (chartH / 4) * i;
596	      ctx.beginPath();
597	      ctx.moveTo(padL, y);
598	      ctx.lineTo(W - padR, y);
599	      ctx.stroke();
600	    }
601	  }
602	
603	  // 折线
604	  var lineColor = color || "#4fc3f7";
605	  ctx.beginPath();
606	  ctx.strokeStyle = lineColor;
607	  ctx.lineWidth = 1.5;
608	  var firstX, firstY, lastX, lastY;
609	  for (var i = 0; i < prices.length; i++) {
610	    var x = padL + (i / (prices.length - 1)) * chartW;
611	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
612	    if (i === 0) {
613	      ctx.moveTo(x, y);
614	      firstX = x;
615	      firstY = y;
616	    } else {
617	      ctx.lineTo(x, y);
618	    }
619	    if (i === prices.length - 1) {
620	      lastX = x;
621	      lastY = y;
622	    }
623	  }
624	  ctx.stroke();
625	
626	  // 渐变填充
627	  var grad = ctx.createLinearGradient(0, padT, 0, H - padB);
628	  grad.addColorStop(0, lineColor + "30");
629	  grad.addColorStop(1, lineColor + "02");
630	  ctx.fillStyle = grad;
631	  ctx.beginPath();
632	  ctx.moveTo(firstX, H - padB);
633	  for (var i = 0; i < prices.length; i++) {
634	    var x = padL + (i / (prices.length - 1)) * chartW;
635	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
636	    if (i === 0) ctx.lineTo(x, y);
637	    else ctx.lineTo(x, y);
638	  }
639	  ctx.lineTo(lastX, H - padB);
640	  ctx.closePath();
641	  ctx.fill();
642	
643	  // 当前价格
644	  var lastPrice = prices[prices.length - 1];
645	  var prevPrice = prices.length >= 2 ? prices[prices.length - 2] : lastPrice;
646	  var chg = lastPrice - prevPrice;
647	  var chgPct = prevPrice !== 0 ? ((chg / prevPrice) * 100).toFixed(2) : "0.00";
648	  var chgText = (chg >= 0 ? "+" : "") + chgPct + "%";
649	
650	  ctx.fillStyle = lineColor;
651	  ctx.font = "bold 11px sans-serif";
652	  ctx.textAlign = "left";
653	  ctx.fillText(lastPrice.toFixed(2), padL + 2, padT + 10);
654	
655	  ctx.fillStyle = chg >= 0 ? "#4caf50" : "#f44336";
656	  ctx.font = "9px sans-serif";
657	  ctx.fillText(chgText, padL + 2, padT + 21);
658	}
