function renderStocks(area, inv, state, parent) {
  // === 📊 我的持仓汇总 ===
  var holdings = inv.stockHoldings || [];
  var hasHoldings = holdings.length > 0;

  if (hasHoldings) {
    var portfolioDiv = document.createElement("div");
    portfolioDiv.style.cssText = "margin-bottom:12px;padding:12px;background:rgba(0,180,216,0.06);border:1px solid var(--accent);border-radius:8px;";
    var totalPL = 0, totalValue = 0;
    var rowsHtml = "";
    for (var hIdx = 0; hIdx < holdings.length; hIdx++) {
      var h = holdings[hIdx];
      var mkt = inv.stockMarket[h.symbol];
      var curPx = mkt ? mkt.price : 0;
      var val = curPx * h.shares;
      var pl = (curPx - h.avgPrice) * h.shares;
      var plPct = h.avgPrice > 0 ? ((curPx - h.avgPrice) / h.avgPrice * 100) : 0;
      totalPL += pl;
      totalValue += val;
      var plClr = pl >= 0 ? "var(--success)" : "var(--danger)";
      var plSign = pl >= 0 ? "+" : "";
      // Find stock name
      var stkName = h.symbol;
      for (var si = 0; si < INV_STOCKS.length; si++) {
        if (INV_STOCKS[si].symbol === h.symbol) { stkName = INV_STOCKS[si].name; break; }
      }
      rowsHtml += `
        <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid rgba(255,255,255,0.04);font-size:11px;gap:8px;">
          <span style="font-weight:600;min-width:50px;">${h.symbol}</span>
          <span style="color:var(--text-secondary);min-width:55px;font-size:10px;">${stkName}</span>
          <span style="min-width:40px;text-align:right;">${h.shares}股</span>
          <span style="min-width:55px;text-align:right;font-size:10px;color:var(--text-muted);">均¥${h.avgPrice.toFixed(2)}</span>
          <span style="min-width:55px;text-align:right;">现¥${curPx.toFixed(2)}</span>
          <span style="min-width:60px;text-align:right;">市值¥${Math.round(val).toLocaleString()}</span>
          <span style="min-width:70px;text-align:right;color:${plClr};font-weight:600;">${plSign}¥${Math.round(pl).toLocaleString()}</span>
          <span style="min-width:45px;text-align:right;color:${plClr};font-size:10px;">${plSign}${plPct.toFixed(1)}%</span>
        </div>`;
    }
    var totalClr = totalPL >= 0 ? "var(--success)" : "var(--danger)";
    var totalSign = totalPL >= 0 ? "+" : "";
    portfolioDiv.innerHTML = `
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
        <h4 style="margin:0;font-size:13px;color:var(--accent);">📊 我的持仓</h4>
        <span style="font-size:11px;">总市值 <strong style="color:var(--accent);">¥${Math.round(totalValue).toLocaleString()}</strong> | 总盈亏 <strong style="color:${totalClr};">${totalSign}¥${Math.round(totalPL).toLocaleString()}</strong></span>
      </div>
      <div style="display:flex;justify-content:space-between;padding:4px 0;font-size:10px;color:var(--text-muted);border-bottom:2px solid var(--border);margin-bottom:4px;">
        <span style="min-width:50px;">代码</span><span style="min-width:55px;">名称</span><span style="min-width:40px;text-align:right;">数量</span><span style="min-width:55px;text-align:right;">均价</span><span style="min-width:55px;text-align:right;">现价</span><span style="min-width:60px;text-align:right;">市值</span><span style="min-width:70px;text-align:right;">盈亏</span><span style="min-width:45px;text-align:right;">幅度</span>
      </div>
      ${rowsHtml}
    `;
    area.appendChild(portfolioDiv);
  }

  var grid = document.createElement("div");
  grid.className = "action-cards";
  grid.style.gridTemplateColumns = "repeat(auto-fill,minmax(230px,1fr))";

  for (var i = 0; i < INV_STOCKS.length; i++) {
    var s = INV_STOCKS[i];
    if (s.category !== "股票") continue;
    var m = inv.stockMarket[s.symbol];
    if (!m) continue;
    var h = null;
    for (var j = 0; j < inv.stockHoldings.length; j++) {
      if (inv.stockHoldings[j].symbol === s.symbol) {
        h = inv.stockHoldings[j];
        break;
      }
    }
    var chg =
      m.history.length >= 2
        ? m.price - m.history[m.history.length - 2].price
        : 0;
    var clr = chg >= 0 ? "var(--success)" : "var(--danger)";

    // Canvas ID
    var cid = "chart-" + s.symbol;

    var card = document.createElement("div");
    card.className = "action-card";
    card.style.borderLeft = "3px solid " + clr;
    card.innerHTML =
      '<div style="display:flex;justify-content:space-between;">' +
      "<strong>" +
      s.symbol +
      " " +
      s.name +
      "</strong>" +
      '<span style="color:' +
      clr +
      '">' +
      m.price.toFixed(2) +
      "</span>" +
      "</div>" +
      '<div style="font-size:10px;color:var(--text-muted);">' +
      s.industry +
      " | " +
      s.desc +
      "</div>" +
      (h
        ? '<div style="font-size:10px;margin:4px 0;">' +
          "持仓" +
          h.shares +
          "股 均价" +
          h.avgPrice.toFixed(2) +
          ' 盈亏<span style="color:' +
          clr +
          '">' +
          Math.round((m.price - h.avgPrice) * h.shares) +
          "</span>" +
          "</div>"
        : "") +
      '<div style="display:flex;gap:3px;margin-top:4px;">' +
      '<button class="btn btn-sm btn-success ibuy" data-s="' +
      s.symbol +
      '" data-q="10">买10</button>' +
      '<button class="btn btn-sm btn-success ibuy" data-s="' +
      s.symbol +
      '" data-q="100">买100</button>' +
      '<button class="btn btn-sm btn-danger isell" data-s="' +
      s.symbol +
      '" data-q="10">卖10</button>' +
      '<button class="btn btn-sm btn-danger isell" data-s="' +
      s.symbol +
      '" data-q="' +
      (h ? h.shares : 0) +
      '">全卖</button>' +
      "</div>" +
      '<canvas id="' +
      cid +
      '" width="200" height="60" style="width:200px;height:60px;margin-top:4px;background:rgba(0,0,0,0.15);border-radius:3px;"></canvas>';
    grid.appendChild(card);
  }

  area.appendChild(grid);

  setTimeout(function () {
    // Draw charts
    for (var i = 0; i < INV_STOCKS.length; i++) {
      var s = INV_STOCKS[i];
      if (s.category !== "股票") continue;
      var m = inv.stockMarket[s.symbol];
      if (m) drawPriceChart("chart-" + s.symbol, m.history, "#4fc3f7");
    }
    // Bind buy/sell
    area.querySelectorAll(".ibuy").forEach(function (b) {
      b.onclick = function () {
        buyInvStock(this.dataset.s, parseInt(this.dataset.q));
        renderInvestmentTab(state, parent);
      };
    });
    area.querySelectorAll(".isell").forEach(function (b) {
      b.onclick = function () {
        sellInvStock(this.dataset.s, parseInt(this.dataset.q));
        renderInvestmentTab(state, parent);
      };
    });
  }, 0);
}

// ---- 子tab渲染：比特币 ----
function renderBtc(area, inv, state, parent) {
  var btcPrice = inv.btcPrice;
  var hold = inv.btcHoldings || 0;
  var fg = inv.btcFearGreed || 50;
  var fgColor = fg > 60 ? "#f44336" : fg > 40 ? "#ff9800" : "#4caf50";
  var fgLabel = fg > 60 ? "贪婪" : fg > 40 ? "中性" : "恐惧";
  var btcAvgCost = inv.btcAvgCost || 0;
  var btcPl = hold > 0 && btcAvgCost > 0 ? (btcPrice - btcAvgCost) * hold : 0;
  var btcPlPct = hold > 0 && btcAvgCost > 0 ? ((btcPrice - btcAvgCost) / btcAvgCost * 100) : 0;
  var plClr = btcPl >= 0 ? "var(--success)" : "var(--danger)";
  var plSign = btcPl >= 0 ? "+" : "";

  var div = document.createElement("div");
  div.innerHTML =
    '<div style="display:flex;gap:12px;flex-wrap:wrap;">' +
    '<div class="action-card" style="flex:2;min-width:200px;padding:12px;">' +
    '<div style="font-size:12px;color:var(--text-muted);">比特币价格 (BTC/USD)</div>' +
    '<div style="font-size:24px;font-weight:bold;color:var(--accent);">' +
    btcPrice.toLocaleString() +
    "</div>" +
    '<div style="font-size:11px;margin-top:4px;">' +
    "持仓: " +
    hold.toFixed(4) +
    " BTC (市值: " +
    Math.round(btcPrice * hold).toLocaleString() +
    ")" +
    "</div>" +
    (hold > 0 && btcAvgCost > 0 ?
      '<div style="font-size:11px;margin-top:4px;color:' + plClr + ';">成本均: ¥' + btcAvgCost.toLocaleString() + ' | 盈亏: ' + plSign + '¥' + Math.round(btcPl).toLocaleString() + ' (' + plSign + btcPlPct.toFixed(2) + '%)</div>' :
      (hold > 0 ? '<div style="font-size:11px;margin-top:4px;color:var(--text-muted);">盈亏数据下次购买后开始追踪</div>' : '')) +
    "</div>" +
    '<div class="action-card" style="flex:1;min-width:100px;padding:12px;text-align:center;">' +
    '<div style="font-size:12px;color:var(--text-muted);">恐惧贪婪指数</div>' +
    '<div style="font-size:28px;font-weight:bold;color:' +
    fgColor +
    ';">' +
    fg +
    "</div>" +
    '<div style="font-size:11px;color:' +
    fgColor +
    ';">' +
    fgLabel +
    "</div>" +
    "</div>" +
    "</div>" +
    '<canvas id="chart-btc" width="300" height="120" style="width:300px;height:120px;margin-top:8px;background:rgba(0,0,0,0.15);border-radius:4px;"></canvas>' +
    '<div style="display:flex;gap:4px;margin-top:8px;">' +
    '<button class="btn btn-sm btn-success" id="btc-buy-0p01">买0.01</button>' +
    '<button class="btn btn-sm btn-success" id="btc-buy-0p1">买0.1</button>' +
    '<button class="btn btn-sm btn-success" id="btc-buy-1">买1</button>' +
    '<button class="btn btn-sm btn-danger" id="btc-sell-0p01">卖0.01</button>' +
    '<button class="btn btn-sm btn-danger" id="btc-sell-0p1">卖0.1</button>' +
    '<button class="btn btn-sm btn-danger" id="btc-sell-all">全卖</button>' +
    "</div>";

  area.appendChild(div);

  setTimeout(function () {
    drawPriceChart("chart-btc", inv.btcHistory || [], "#f7931a");

    var bind = function (id, fn) {
      var el = document.getElementById(id);
      if (el) el.onclick = fn;
    };
    bind("btc-buy-0p01", function () {
      buyBtc(0.01);
      renderInvestmentTab(state, parent);
    });
    bind("btc-buy-0p1", function () {
      buyBtc(0.1);
      renderInvestmentTab(state, parent);
    });
    bind("btc-buy-1", function () {
      buyBtc(1);
      renderInvestmentTab(state, parent);
    });
    bind("btc-sell-0p01", function () {
      sellBtc(0.01);
      renderInvestmentTab(state, parent);
    });
    bind("btc-sell-0p1", function () {
      sellBtc(0.1);
      renderInvestmentTab(state, parent);
    });
    bind("btc-sell-all", function () {
      sellBtc(hold);
      renderInvestmentTab(state, parent);
    });
  }, 0);
}

